package com.bitedash.controller; import com.bitedash.dto.*; import com.bitedash.service.RestaurantService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/restaurants") public class RestaurantController{private final RestaurantService service; public RestaurantController(RestaurantService s){service=s;} @GetMapping public List<RestaurantResponse> search(@RequestParam(required=false) String search,@RequestParam(required=false) String category){return service.search(search,category);} @GetMapping("/{id}/items") public List<FoodItemResponse> items(@PathVariable Long id){return service.items(id);}}
